383: 		if matchAnchor(seenAnchor, targetFile, workspaceRoot) {
384: 			ids, err := idx.LookupByAnchor(ctx, seenAnchor)
385: 			if err == nil && len(ids) > 0 {
386: 				return true
387: 			}
388: 		}
389: 	}
