package delivery

import (
	"context"
	"regexp"
	"strings"
	"unicode"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/dossiers"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

type Engine struct {
	index         *index.Index
	projector     *dossiers.Projector
	scopeResolver *config.ScopeResolver
	workspaceRoot string
	budgets       map[Moment]int
}

type EngineOption func(*Engine)

func WithBudgets(budgets map[Moment]int) EngineOption {
	return func(e *Engine) {
		e.budgets = budgets
	}
}

func WithScopeResolver(resolver *config.ScopeResolver) EngineOption {
	return func(e *Engine) {
		e.scopeResolver = resolver
	}
}

func NewEngine(idx *index.Index, workspaceRoot string, opts ...EngineOption) *Engine {
	e := &Engine{
		index:         idx,
		workspaceRoot: workspaceRoot,
		budgets:       DefaultBudgets(),
	}
	for _, opt := range opts {
		opt(e)
	}
	return e
}

func (e *Engine) filterAndVerify(entries []dossiers.Entry) []dossiers.Entry {
	var valid []dossiers.Entry
	for _, ent := range entries {
		if ent.Retired {
			continue
		}
		if len(ent.Anchors) > 0 {
			verified, _ := VerifyAnchors(ent.Anchors, e.workspaceRoot)
			if len(verified) == 0 {
				continue // skip if all suspect
			}
			ent.Anchors = verified
		}
		valid = append(valid, ent)
	}
	return valid
}

// sanitizeFTSQuery converts raw prompt terms into a safe FTS5 query.
// Each term is stripped of non-alphanumeric characters, quoted, and joined with OR.
func sanitizeFTSQuery(terms []string) string {
	var clean []string
	for _, term := range terms {
		// Strip non-word characters
		stripped := strings.Map(func(r rune) rune {
			if unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' {
				return r
			}
			return -1
		}, term)
		if len(stripped) < 3 {
			continue
		}
		// Double any embedded quotes and wrap in quotes for FTS5
		escaped := strings.ReplaceAll(stripped, `"`, `""`)
		clean = append(clean, `"`+escaped+`"`)
	}
	if len(clean) == 0 {
		return ""
	}
	return strings.Join(clean, " OR ")
}

func (e *Engine) TaskStartEntries(ctx context.Context, promptTerms []string, diffPaths []string) ([]RankedEntry, error) {
	entryMap := make(map[string]dossiers.Entry)

	// Query by prompt terms — search errors do NOT discard diff-path results.
	if len(promptTerms) > 0 {
		query := sanitizeFTSQuery(promptTerms)
		if query != "" {
			results, err := e.index.SearchEntries(ctx, query)
			if err == nil {
				for _, ent := range results {
					entryMap[ent.ID] = ent
				}
			}
			// On error, log/ignore — diff-path results still proceed.
		}
	}

	// Query by diff paths (these are repo-relative, matching anchor format).
	for _, path := range diffPaths {
		ids, err := e.index.LookupByAnchor(ctx, path)
		if err != nil {
			continue // don't let one bad path kill the whole lookup
		}
		for _, id := range ids {
			if _, exists := entryMap[id]; !exists {
				ent, err := e.index.GetEntry(ctx, id)
				if err == nil && ent != nil {
					entryMap[id] = *ent
				}
			}
		}
	}

	var entries []dossiers.Entry
	for _, ent := range entryMap {
		entries = append(entries, ent)
	}

	validEntries := e.filterAndVerify(entries)
	ranked := RankEntries(validEntries, diffPaths)
	return SelectWithinBudget(ranked, e.budgets[MomentTaskStart]), nil
}

func (e *Engine) DossierEntries(ctx context.Context, scope string) ([]RankedEntry, error) {
	entries, err := e.index.ListEntriesByScope(ctx, scope)
	if err != nil {
		return nil, err
	}

	var valid []dossiers.Entry
	for _, ent := range entries {
		if ent.Type == dossiers.EntryTypeInvariant || ent.Type == dossiers.EntryTypeFailureSignature || ent.Type == dossiers.EntryTypeRuledOut {
			valid = append(valid, ent)
		}
	}

	validEntries := e.filterAndVerify(valid)
	ranked := RankEntries(validEntries, nil)
	return SelectWithinBudget(ranked, e.budgets[MomentFirstEntry]), nil
}

func (e *Engine) AnchorEntries(ctx context.Context, anchor string) ([]RankedEntry, error) {
	if !VerifyAnchor(anchor, e.workspaceRoot) {
		return nil, nil
	}

	ids, err := e.index.LookupByAnchor(ctx, anchor)
	if err != nil {
		return nil, err
	}

	var entries []dossiers.Entry
	for _, id := range ids {
		ent, err := e.index.GetEntry(ctx, id)
		if err == nil && ent != nil {
			entries = append(entries, *ent)
		}
	}

	validEntries := e.filterAndVerify(entries)
	ranked := RankEntries(validEntries, []string{anchor})
	return SelectWithinBudget(ranked, e.budgets[MomentFirstTouch]), nil
}

// patternMatchesOutput returns true if the pattern matches the tool output.
// Tries regexp first; falls back to substring match.
func patternMatchesOutput(pattern, output string) bool {
	if pattern == "" {
		return false
	}
	re, err := regexp.Compile(pattern)
	if err == nil {
		return re.MatchString(output)
	}
	// Fallback: case-insensitive substring match
	return strings.Contains(strings.ToLower(output), strings.ToLower(pattern))
}

func (e *Engine) ErrorEntries(ctx context.Context, commandPrefix string, output string) ([]RankedEntry, error) {
	results, err := e.index.LookupErrorPatterns(ctx, commandPrefix)
	if err != nil {
		return nil, err
	}

	var entries []dossiers.Entry
	for _, res := range results {
		// Filter: pattern must match the actual output
		if !patternMatchesOutput(res.Pattern, output) {
			continue
		}
		ent, err := e.index.GetEntry(ctx, res.EntryID)
		if err == nil && ent != nil {
			entries = append(entries, *ent)
		}
	}

	validEntries := e.filterAndVerify(entries)
	ranked := RankEntries(validEntries, nil)
	return SelectWithinBudget(ranked, e.budgets[MomentError]), nil
}

// isGateEntry detects whether an entry is marked as a gate.
// Uses case-insensitive matching for the structured "gate:" tag.
func isGateEntry(ent *dossiers.Entry) bool {
	gatePattern := regexp.MustCompile(`(?i)\bgate:\s*edit\b`)
	return gatePattern.MatchString(ent.Text) ||
		gatePattern.MatchString(ent.ClosesWhen) ||
		gatePattern.MatchString(ent.Verified)
}

func (e *Engine) GateEntries(ctx context.Context, targetFile string, ledger *Ledger) ([]RankedEntry, error) {
	// Use exact anchor match for gates to avoid LIKE wildcards matching unrelated files.
	ids, err := e.index.LookupByAnchorExact(ctx, targetFile)
	if err != nil {
		return nil, err
	}
	// Fall back to prefix match if exact yields nothing
	if len(ids) == 0 {
		ids, err = e.index.LookupByAnchor(ctx, targetFile)
		if err != nil {
			return nil, err
		}
	}

	var entries []dossiers.Entry
	for _, id := range ids {
		if ledger != nil && ledger.IsGateAcknowledged(id) {
			continue
		}

		ent, err := e.index.GetEntry(ctx, id)
		if err == nil && ent != nil {
			if isGateEntry(ent) {
				entries = append(entries, *ent)
			}
		}
	}

	validEntries := e.filterAndVerify(entries)
	ranked := RankEntries(validEntries, []string{targetFile})
	return SelectWithinBudget(ranked, e.budgets[MomentGate]), nil
}

package antigravity

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/delivery"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

var editIntentPattern = regexp.MustCompile(`(?i)\b(?:edit|modify|change|update|write\s+to|replace)\s+(?:the\s+file\s+|file\s+)?[` + "`" + `"'` + `]?([a-zA-Z0-9_\-./\\]+)`)

type PreInvocationPayload struct {
	ConversationID      string   `json:"conversationId"`
	ConversationIDSnake string   `json:"conversation_id"`
	InvocationNum       int      `json:"invocationNum"`
	InitialNumSteps     int      `json:"initialNumSteps"`
	UserPrompt          string   `json:"userPrompt"`
	TranscriptPath      string   `json:"transcriptPath"`
	TranscriptPathSnake string   `json:"transcript_path"`
	WorkspacePaths      []string `json:"workspacePaths"`
	WorkspacePathsSnake []string `json:"workspace_paths"`
}

func (p *PreInvocationPayload) Normalize() {
	if p.ConversationID == "" {
		p.ConversationID = p.ConversationIDSnake
	}
	if p.TranscriptPath == "" {
		p.TranscriptPath = p.TranscriptPathSnake
	}
	if len(p.WorkspacePaths) == 0 {
		p.WorkspacePaths = p.WorkspacePathsSnake
	}
}

func HandlePreInvocation(ctx context.Context, payload []byte, opts ...HookOption) ([]byte, error) {
	var input PreInvocationPayload
	if err := json.Unmarshal(payload, &input); err != nil {
		return []byte("{}"), nil
	}
	input.Normalize()

	if os.Getenv("REPO_MEMORY_DISABLED") == "1" {
		return []byte("{}"), nil
	}
	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" {
		return []byte("{}"), nil
	}

	var hookOpts HookOptions
	for _, opt := range opts {
		if opt != nil {
			opt(&hookOpts)
		}
	}

	workspaceRoot := hookOpts.WorkspaceOverride
	if workspaceRoot == "" {
		if len(input.WorkspacePaths) > 0 {
			workspaceRoot = input.WorkspacePaths[0]
		} else {
			workspaceRoot, _ = os.Getwd()
		}
	}
	if workspaceRoot == "" {
		return []byte("{}"), nil
	}

	if !config.IsEnrolledFast(workspaceRoot) {
		return []byte("{}"), nil
	}

	dataDir := hookOpts.DataDir
	if dataDir == "" {
		dataDir = config.DataDir()
	}

	repoID := ""
	if entry, found, _ := config.FindRegistryEntry(dataDir, workspaceRoot); found && entry != nil {
		repoID = entry.RepoID
	}
	if repoID == "" {
		cmd := exec.Command("git", "rev-parse", "--show-toplevel")
		cmd.Dir = workspaceRoot
		out, err := cmd.Output()
		if err == nil {
			repoID = filepath.Base(strings.TrimSpace(string(out)))
		}
	}
	if repoID == "" {
		return []byte("{}"), nil
	}

	idxPath := filepath.Join(dataDir, repoID, "index.db")
	idx, err := index.NewIndex(idxPath)
	if err != nil {
		return []byte("{}"), nil
	}
	defer idx.Close()

	engine := delivery.NewEngine(idx, workspaceRoot)

	ledger, err := LoadLedger(dataDir, repoID, input.ConversationID)
	if err != nil || ledger == nil {
		ledger = delivery.NewLedger(input.ConversationID)
	}

	var injectSteps []InjectStep

	// First-entry and first-touch moments
	var touchedFiles []string
	var steps []Step
	if input.TranscriptPath != "" {
		steps, _ = ParseTranscript(filepath.Dir(input.TranscriptPath))
		if len(steps) > 0 {
			seenPaths := make(map[string]bool)
			for _, step := range steps {
				if len(step.ToolCalls) == 0 {
					continue
				}
				var calls []map[string]any
				if err := json.Unmarshal(step.ToolCalls, &calls); err != nil {
					continue
				}
				for _, call := range calls {
					fn, ok := call["function"].(map[string]any)
					if !ok {
						continue
					}
					argsStr, ok := fn["arguments"].(string)
					if !ok || argsStr == "" {
						continue
					}
					var args map[string]any
					if err := json.Unmarshal([]byte(argsStr), &args); err != nil {
						continue
					}
					for _, v := range args {
						str, ok := v.(string)
						if !ok {
							continue
						}
						// If path is absolute and within workspace
						if strings.HasPrefix(str, workspaceRoot) {
							if !seenPaths[str] {
								seenPaths[str] = true
								touchedFiles = append(touchedFiles, str)
							}
						}
					}
				}
			}
		}
	}

	// Compaction Detection — only re-detect if we haven't already handled this checkpoint.
	if len(ledger.Injections) > 0 && len(steps) > 0 {
		res := DetectCompaction(steps, ledger)
		if res.Detected && res.CheckpointStepIdx > ledger.LastHandledCheckpointStep {
			var checkpointText string
			checkpointFound := false
			for _, step := range steps {
				if step.IsCheckpoint {
					checkpointFound = true
				} else if checkpointFound {
					if step.Type == "PLANNER_RESPONSE" || strings.Contains(step.Content, "[repo-memory") {
						checkpointText += step.Content
					}
				}
			}

			reinjStep, err := BuildReinjection(ctx, idx, res.LostInjections, checkpointText, 1000)
			if err == nil && reinjStep != nil {
				injectSteps = append(injectSteps, *reinjStep)
				ledger.RearmDedup()
			}
			// Mark this checkpoint as handled so we don't re-inject on future turns.
			ledger.LastHandledCheckpointStep = res.CheckpointStepIdx
		}
	}

	// Task start moment — only on the first invocation of a new user turn.
	if input.InvocationNum == 0 && input.InitialNumSteps <= 1 {
		var promptTerms []string
		for _, term := range strings.Fields(input.UserPrompt) {
			if len(term) >= 3 {
				promptTerms = append(promptTerms, term)
			}
		}

		// Diff paths: git already returns repo-relative paths — keep them as-is.
		// Guard against single-commit repos where HEAD~1 would fail.
		var diffPaths []string
		cmd := exec.CommandContext(ctx, "git", "diff", "--name-only", "HEAD~1")
		cmd.Dir = workspaceRoot
		if out, err := cmd.Output(); err == nil {
			lines := strings.Split(string(bytes.TrimSpace(out)), "\n")
			for _, line := range lines {
				line = strings.TrimSpace(line)
				if line != "" {
					diffPaths = append(diffPaths, line)
				}
			}
		}
		// err is intentionally ignored — single-commit repos just get no diff paths.

		entries, err := engine.TaskStartEntries(ctx, promptTerms, diffPaths)
		if err == nil && len(entries) > 0 {
			formatted := delivery.FormatEntries(entries)
			injectSteps = append(injectSteps, InjectStep{
				SystemMessage: &SystemMessageEntry{
					SystemMessage: formatted,
					Metadata:      map[string]string{"moment": "task-start"},
				},
			})
			for _, ent := range entries {
				ledger.RecordInjection(delivery.InjectionRecord{
					EntryID:   ent.Entry.ID,
					Channel:   "systemMessage",
					Moment:    delivery.MomentTaskStart,
					StepIndex: input.InitialNumSteps,
				})
			}
		}
	}

	// Mid-turn moments: first-touch and first-entry.
	// These run on every invocation, gated by ledger dedup (HasSeenAnchor/HasSeenDossier).
	for _, path := range touchedFiles {
		anchor := path
		if rel, err := filepath.Rel(workspaceRoot, path); err == nil && !strings.HasPrefix(rel, "..") {
			anchor = rel
		}

		// Unique anchor
		if !ledger.HasSeenAnchor(anchor) && !ledger.HasSeenAnchor(path) {
			entries, err := engine.AnchorEntries(ctx, anchor)
			if (err != nil || len(entries) == 0) && anchor != path {
				entries, err = engine.AnchorEntries(ctx, path)
			}
			if err == nil && len(entries) > 0 {
				formatted := delivery.FormatEntries(entries)
				injectSteps = append(injectSteps, InjectStep{
					SystemMessage: &SystemMessageEntry{
						SystemMessage: formatted,
						Metadata:      map[string]string{"moment": "first-touch", "anchor": anchor},
					},
				})
				for _, ent := range entries {
					ledger.RecordInjection(delivery.InjectionRecord{
						EntryID:   ent.Entry.ID,
						Channel:   "systemMessage",
						Moment:    delivery.MomentFirstTouch,
						StepIndex: input.InitialNumSteps,
					})
				}
			}
			ledger.MarkAnchorSeen(anchor)
			ledger.MarkAnchorSeen(path)
		}
	}

	// Scopes
	if len(touchedFiles) > 0 {
		moduleScopes := config.DeriveModuleScopes(touchedFiles)
		for _, mScope := range moduleScopes {
			scopeName := mScope.Name
			if !ledger.HasSeenDossier(scopeName) {
				entries, err := engine.DossierEntries(ctx, scopeName)
				if err == nil && len(entries) > 0 {
					formatted := delivery.FormatEntries(entries)
					injectSteps = append(injectSteps, InjectStep{
						SystemMessage: &SystemMessageEntry{
							SystemMessage: formatted,
							Metadata:      map[string]string{"moment": "first-entry", "scope": scopeName},
						},
					})
					for _, ent := range entries {
						ledger.RecordInjection(delivery.InjectionRecord{
							EntryID:   ent.Entry.ID,
							Channel:   "systemMessage",
							Moment:    delivery.MomentFirstEntry,
							StepIndex: input.InitialNumSteps,
						})
					}
				}
				ledger.MarkDossierSeen(scopeName)
			}
		}
	}

	// About-to-edit moment — runs mid-turn too, with dedup via ledger.
	if len(steps) > 0 {
		var latestPlanner *Step
		for i := len(steps) - 1; i >= 0; i-- {
			if strings.EqualFold(steps[i].Type, "PLANNER_RESPONSE") {
				latestPlanner = &steps[i]
				break
			}
		}

		if latestPlanner != nil {
			text := latestPlanner.Thinking + "\n" + latestPlanner.Content
			matches := editIntentPattern.FindAllStringSubmatch(text, -1)
			seenTarget := make(map[string]bool)
			for _, m := range matches {
				target := strings.Trim(m[1], "`'\" \t\r\n.,;:()")
				if target == "" || seenTarget[target] {
					continue
				}
				seenTarget[target] = true

				if hasEntriesInContext(ctx, idx, ledger, workspaceRoot, target) {
					filename := filepath.Base(target)
					injectSteps = append(injectSteps, InjectStep{
						EphemeralMessage: fmt.Sprintf("[repo-memory] Check injected entries above before editing %s", filename),
					})
					// Record with the target file as the entry identifier for dedup
					ledger.RecordInjection(delivery.InjectionRecord{
						EntryID:   "about-to-edit:" + target,
						Channel:   delivery.ChannelEphemeral,
						Moment:    delivery.MomentAboutToEdit,
						StepIndex: input.InitialNumSteps,
					})
					break
				}
			}
		}
	}

	if err := SaveLedger(dataDir, repoID, ledger); err != nil {
		// Log but don't fail — delivery should still work without persistence
	}

	if len(injectSteps) == 0 {
		return []byte("{}"), nil
	}

	resp := InjectStepsResponse{
		InjectSteps: injectSteps,
	}
	out, err := json.Marshal(resp)
	if err != nil {
		return []byte("{}"), nil
	}
	return out, nil
}

func matchAnchor(anchor, target, workspaceRoot string) bool {
	cleanA := filepath.Clean(anchor)
	cleanT := filepath.Clean(target)
	if cleanA == cleanT {
		return true
	}
	if filepath.Join(workspaceRoot, cleanA) == filepath.Join(workspaceRoot, cleanT) {
		return true
	}
	if strings.HasSuffix(cleanA, "/"+cleanT) || strings.HasSuffix(cleanT, "/"+cleanA) {
		return true
	}
	if !strings.Contains(cleanT, string(filepath.Separator)) && filepath.Base(cleanA) == cleanT {
		return true
	}
	if !strings.Contains(cleanA, string(filepath.Separator)) && filepath.Base(cleanT) == cleanA {
		return true
	}
	return false
}

func hasEntriesInContext(ctx context.Context, idx *index.Index, ledger *delivery.Ledger, workspaceRoot, targetFile string) bool {
	for _, inj := range ledger.Injections {
		if inj.EntryID == "" || strings.HasPrefix(inj.EntryID, "about-to-edit:") {
			continue
		}
		ent, err := idx.GetEntry(ctx, inj.EntryID)
		if err == nil && ent != nil {
			for _, a := range ent.Anchors {
				if matchAnchor(a, targetFile, workspaceRoot) {
					return true
				}
			}
		}
	}

	for seenAnchor := range ledger.SeenAnchors {
		if matchAnchor(seenAnchor, targetFile, workspaceRoot) {
			ids, err := idx.LookupByAnchor(ctx, seenAnchor)
			if err == nil && len(ids) > 0 {
				return true
			}
		}
	}

	return false
}

