package antigravity

import (
	"context"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/delivery"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

var allowResponse = []byte(`{"decision":"allow"}`)

type PreToolUsePayload struct {
	ConversationID      string   `json:"conversationId"`
	ConversationIDSnake string   `json:"conversation_id"`
	InvocationNum       int      `json:"invocationNum"`
	ToolName            string   `json:"toolName"`
	ToolCall            struct {
		Name string          `json:"name"`
		Args json.RawMessage `json:"args"`
	} `json:"toolCall"`
	TranscriptPath      string   `json:"transcriptPath"`
	TranscriptPathSnake string   `json:"transcript_path"`
	WorkspacePaths      []string `json:"workspacePaths"`
	WorkspacePathsSnake []string `json:"workspace_paths"`
}

func (p *PreToolUsePayload) Normalize() {
	if p.ConversationID == "" {
		p.ConversationID = p.ConversationIDSnake
	}
	if p.TranscriptPath == "" {
		p.TranscriptPath = p.TranscriptPathSnake
	}
	if len(p.WorkspacePaths) == 0 {
		p.WorkspacePaths = p.WorkspacePathsSnake
	}
	if p.ToolName == "" && p.ToolCall.Name != "" {
		p.ToolName = p.ToolCall.Name
	}
}

type PreToolUseResponse struct {
	Decision string `json:"decision"` // "allow", "deny", "ask", "force_ask"
	Reason   string `json:"reason,omitempty"`
}

type toolArgs struct {
	TargetFile      string `json:"TargetFile"`
	TargetFileCamel string `json:"targetFile"`
	TargetFileSnake string `json:"target_file"`
	FilePath        string `json:"filePath"`
	FilePathSnake   string `json:"file_path"`
	Path            string `json:"path"`
}

func isEditTool(name string) bool {
	return strings.EqualFold(name, "replace_file_content") || strings.EqualFold(name, "write_to_file")
}

func extractTargetFile(argsRaw json.RawMessage) string {
	if len(argsRaw) == 0 {
		return ""
	}
	var args toolArgs
	if err := json.Unmarshal(argsRaw, &args); err != nil {
		var s string
		if errStr := json.Unmarshal(argsRaw, &s); errStr == nil {
			_ = json.Unmarshal([]byte(s), &args)
		}
	}
	for _, p := range []string{args.TargetFile, args.TargetFileCamel, args.TargetFileSnake, args.FilePath, args.FilePathSnake, args.Path} {
		if strings.TrimSpace(p) != "" {
			return strings.TrimSpace(p)
		}
	}
	return ""
}

func HandlePreToolUse(ctx context.Context, payload []byte, opts ...HookOption) ([]byte, error) {
	if os.Getenv("REPO_MEMORY_DISABLED") == "1" {
		return allowResponse, nil
	}
	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" {
		return allowResponse, nil
	}

	var input PreToolUsePayload
	if err := json.Unmarshal(payload, &input); err != nil {
		return allowResponse, nil
	}
	input.Normalize()

	if !isEditTool(input.ToolName) {
		return allowResponse, nil
	}

	var hookOpts HookOptions
	for _, opt := range opts {
		if opt != nil {
			opt(&hookOpts)
		}
	}

	workspaceRoot := hookOpts.WorkspaceOverride
	if workspaceRoot == "" {
		if len(input.WorkspacePaths) > 0 {
			workspaceRoot = input.WorkspacePaths[0]
		} else {
			workspaceRoot, _ = os.Getwd()
		}
	}
	if workspaceRoot == "" {
		return allowResponse, nil
	}

	if !config.IsEnrolledFast(workspaceRoot) {
		return allowResponse, nil
	}

	dataDir := hookOpts.DataDir
	if dataDir == "" {
		dataDir = config.DataDir()
	}

	repoID := ""
	if entry, found, _ := config.FindRegistryEntry(dataDir, workspaceRoot); found && entry != nil {
		repoID = entry.RepoID
	}
	if repoID == "" {
		cmd := exec.Command("git", "rev-parse", "--show-toplevel")
		cmd.Dir = workspaceRoot
		out, err := cmd.Output()
		if err == nil {
			repoID = filepath.Base(strings.TrimSpace(string(out)))
		}
	}
	if repoID == "" {
		return allowResponse, nil
	}

	targetFile := extractTargetFile(input.ToolCall.Args)
	if targetFile == "" {
		return allowResponse, nil
	}

	idxPath := filepath.Join(dataDir, repoID, "index.db")
	idx, err := index.NewIndex(idxPath)
	if err != nil {
		return allowResponse, nil
	}
	defer idx.Close()

	engine := delivery.NewEngine(idx, workspaceRoot)

	// Load the persisted ledger so gate acknowledgments survive across hook invocations.
	ledger, err := LoadLedger(dataDir, repoID, input.ConversationID)
	if err != nil || ledger == nil {
		ledger = delivery.NewLedger(input.ConversationID)
	}

	targetClean := filepath.Clean(targetFile)
	relPath := targetClean
	if filepath.IsAbs(targetClean) {
		if rel, err := filepath.Rel(workspaceRoot, targetClean); err == nil && !strings.HasPrefix(rel, "..") {
			relPath = rel
		}
	}

	entries, err := engine.GateEntries(ctx, relPath, ledger)
	if (err != nil || len(entries) == 0) && relPath != targetClean {
		entries, err = engine.GateEntries(ctx, targetClean, ledger)
	}
	if err != nil || len(entries) == 0 {
		return allowResponse, nil
	}

	// Acknowledge the gate for all matched entries so re-issued edits pass through.
	for _, ent := range entries {
		ledger.AcknowledgeGate(ent.Entry.ID)
	}
	_ = SaveLedger(dataDir, repoID, ledger)

	reason := delivery.FormatGateDeny(entries[0].Entry)
	resp := PreToolUseResponse{
		Decision: "force_ask",
		Reason:   reason,
	}
	out, err := json.Marshal(resp)
	if err != nil {
		return allowResponse, nil
	}
	return out, nil
}

package antigravity

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sync"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/delivery"
)

var (
	ledgerStoreMutex sync.Mutex
	// safeIDPattern matches UUIDs, hex strings, and other path-safe identifiers.
	safeIDPattern = regexp.MustCompile(`^[a-zA-Z0-9_\-]+$`)
)

// sanitizeConversationID ensures the conversation ID is safe for use in a filesystem path.
// Empty, path-traversal, or non-alphanumeric IDs are hashed to a safe hex string.
func sanitizeConversationID(id string) string {
	if id == "" {
		return "unknown"
	}
	if safeIDPattern.MatchString(id) && len(id) <= 255 {
		return id
	}
	// Hash unsafe IDs to prevent path traversal and other filesystem issues.
	h := sha256.Sum256([]byte(id))
	return hex.EncodeToString(h[:16])
}

func getLedgerPath(dataDir, repoID, conversationID string) string {
	safeID := sanitizeConversationID(conversationID)
	return filepath.Join(dataDir, repoID, "ledgers", safeID+".json")
}

// SaveLedger atomically persists the ledger to disk using write-to-temp + rename.
func SaveLedger(dataDir, repoID string, ledger *delivery.Ledger) error {
	ledgerStoreMutex.Lock()
	defer ledgerStoreMutex.Unlock()

	path := getLedgerPath(dataDir, repoID, ledger.ConversationID)
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("creating ledger directory: %w", err)
	}

	data, err := json.MarshalIndent(ledger, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling ledger: %w", err)
	}

	// Atomic write: write to a temp file in the same directory, then rename.
	// This prevents readers from seeing a truncated file.
	tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
	if err != nil {
		return fmt.Errorf("creating temp file for ledger: %w", err)
	}
	tmpPath := tmp.Name()

	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		os.Remove(tmpPath)
		return fmt.Errorf("writing ledger temp file: %w", err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("closing ledger temp file: %w", err)
	}

	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("renaming ledger file: %w", err)
	}

	return nil
}

func LoadLedger(dataDir, repoID, conversationID string) (*delivery.Ledger, error) {
	ledgerStoreMutex.Lock()
	defer ledgerStoreMutex.Unlock()

	path := getLedgerPath(dataDir, repoID, conversationID)
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return delivery.NewLedger(conversationID), nil
		}
		return nil, err
	}

	var ledger delivery.Ledger
	if err := json.Unmarshal(data, &ledger); err != nil {
		// Corrupted file (e.g. truncated) — start fresh rather than failing.
		return delivery.NewLedger(conversationID), nil
	}

	// Ensure maps are initialized if they were nil in json
	if ledger.SeenDossiers == nil {
		ledger.SeenDossiers = make(map[string]bool)
	}
	if ledger.SeenAnchors == nil {
		ledger.SeenAnchors = make(map[string]bool)
	}
	if ledger.AcknowledgedGates == nil {
		ledger.AcknowledgedGates = make(map[string]bool)
	}

	return &ledger, nil
}

