package main

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
)

func TestMCPProtocol(t *testing.T) {
	// Build a sequence of JSON-RPC requests separated by newlines.
	var input bytes.Buffer

	// 1. initialize
	writeJSON(&input, map[string]any{
		"jsonrpc": "2.0",
		"id":      1,
		"method":  "initialize",
		"params":  map[string]any{"protocolVersion": "2024-11-05"},
	})

	// 2. notification (no id) — should be silently dropped
	writeJSON(&input, map[string]any{
		"jsonrpc": "2.0",
		"method":  "notifications/initialized",
	})

	// 3. ping
	writeJSON(&input, map[string]any{
		"jsonrpc": "2.0",
		"id":      2,
		"method":  "ping",
	})

	// 4. tools/list
	writeJSON(&input, map[string]any{
		"jsonrpc": "2.0",
		"id":      3,
		"method":  "tools/list",
	})

	// 5. tools/call with missing index (unenrolled) — should return isError
	writeJSON(&input, map[string]any{
		"jsonrpc": "2.0",
		"id":      4,
		"method":  "tools/call",
		"params":  map[string]any{"name": "memory_brief", "arguments": map[string]any{"scope": "test"}},
	})

	// 6. unknown method
	writeJSON(&input, map[string]any{
		"jsonrpc": "2.0",
		"id":      5,
		"method":  "nonexistent/method",
	})

	var output bytes.Buffer
	cmd := mcpCmd
	cmd.SetIn(&input)
	cmd.SetOut(&output)
	cmd.SetErr(&bytes.Buffer{})

	// The command will exit when stdin is exhausted — that's expected.
	// We can't easily set up an enrolled workspace here, so unenrolled tools
	// return isError results. We test the protocol framing.
	_ = cmd.Execute()

	lines := strings.Split(strings.TrimSpace(output.String()), "\n")

	// We expect 5 responses (notification has no response).
	if len(lines) < 5 {
		t.Fatalf("expected at least 5 response lines, got %d:\n%s", len(lines), output.String())
	}

	// 1. initialize response
	resp1 := parseResponse(t, lines[0])
	result1, ok := resp1["result"].(map[string]any)
	if !ok {
		t.Fatalf("initialize: expected result object, got %v", resp1)
	}
	if result1["protocolVersion"] != "2024-11-05" {
		t.Errorf("initialize: expected protocolVersion 2024-11-05, got %v", result1["protocolVersion"])
	}
	serverInfo, ok := result1["serverInfo"].(map[string]any)
	if !ok || serverInfo["name"] != "repo-memory" {
		t.Errorf("initialize: expected serverInfo.name=repo-memory, got %v", result1["serverInfo"])
	}

	// 2. ping response
	resp2 := parseResponse(t, lines[1])
	result2, ok := resp2["result"].(map[string]any)
	if !ok {
		t.Fatalf("ping: expected result object, got %v", resp2)
	}
	if len(result2) != 0 {
		t.Errorf("ping: expected empty object, got %v", result2)
	}

	// 3. tools/list response
	resp3 := parseResponse(t, lines[2])
	result3, ok := resp3["result"].(map[string]any)
	if !ok {
		t.Fatalf("tools/list: expected result object, got %v", resp3)
	}
	toolsRaw, ok := result3["tools"].([]any)
	if !ok || len(toolsRaw) == 0 {
		t.Fatalf("tools/list: expected non-empty tools array, got %v", result3)
	}
	// Verify tool names use underscores
	for _, tr := range toolsRaw {
		tool, ok := tr.(map[string]any)
		if !ok {
			continue
		}
		name, ok := tool["name"].(string)
		if !ok {
			continue
		}
		if strings.Contains(name, ".") {
			t.Errorf("tools/list: tool name %q contains dot, expected underscores", name)
		}
		// Verify each tool has an inputSchema
		if _, hasSchema := tool["inputSchema"]; !hasSchema {
			t.Errorf("tools/list: tool %q missing inputSchema", name)
		}
	}

	// 4. tools/call response (unenrolled — should be isError)
	resp4 := parseResponse(t, lines[3])
	result4, ok := resp4["result"].(map[string]any)
	if !ok {
		t.Fatalf("tools/call: expected result object, got %v", resp4)
	}
	if result4["isError"] != true {
		t.Errorf("tools/call: expected isError=true for unenrolled repo, got %v", result4)
	}

	// 5. unknown method — should return JSON-RPC error
	resp5 := parseResponse(t, lines[4])
	if _, hasError := resp5["error"]; !hasError {
		t.Errorf("unknown method: expected JSON-RPC error, got %v", resp5)
	}
}

func writeJSON(buf *bytes.Buffer, v any) {
	b, _ := json.Marshal(v)
	buf.Write(b)
	buf.WriteByte('\n')
}

func parseResponse(t *testing.T, line string) map[string]any {
	t.Helper()
	var resp map[string]any
	if err := json.Unmarshal([]byte(line), &resp); err != nil {
		t.Fatalf("failed to parse response: %v\nline: %s", err, line)
	}
	return resp
}

